import{_ as o,a0 as l,w as r,s as u,ao as n,I as i,x as a,a1 as p,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"為你的 Linux 應用創建 .desktop 文件 | LCTT x X-CMD","titleTemplate":false,"description":"為你的 Linux 應用創建 .desktop 文件 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"為你的 Linux 應用創建 .desktop 文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"為你的 Linux 應用創建 .desktop 文件 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20171218 How to Create a .Desktop File For Your Application in Linux","title":"為你的 Linux 應用創建 .desktop 文件","tag":"201801","desc":""},"relativePath":"201801/20171218 How to Create a .Desktop File For Your Application in Linux.md","filePath":"[post].md"}'),c={name:"201801/20171218 How to Create a .Desktop File For Your Application in Linux.md"};function d(h,e,m,k,g,w){const t=l("Link");return r(),u("div",null,[e[16]||(e[16]=n('<h1 id="為你的-linux-應用創建-desktop-文件" tabindex="-1">為你的 Linux 應用創建 .desktop 文件 <a class="header-anchor" href="#為你的-linux-應用創建-desktop-文件" aria-label="Permalink to “為你的 Linux 應用創建 .desktop 文件”">​</a></h1><p><img src="https://www.maketecheasier.com/assets/uploads/2017/12/application-launcher-featured.jpg" alt=""></p><p>在 Linux 中，一個 <code>.desktop</code> 文件就是一個用來運行程序的快捷方式。沒有 <code>.desktop</code> 的話，你的應用就不會在應用菜單中顯示了，也無法使用像 Synapse 和 Albert 這樣的第三方啓動起啓動了。</p><p>大多數應用在安裝後都會自動創建 <code>.desktop</code> 文件，並將自己放入應用菜單中以方便訪問。然而，如果是你自己從源代碼中編譯的程序或者自己下載的壓縮格式的應用，那就不會做這些事情了，每次你都需要打開終端來執行它的二進制文件。顯然這個過程很無聊也很麻煩。</p><p>本文將會告訴你如何為應用創建 <code>.desktop</code> 文件，從而讓你能在應用菜單中啓動該應用。</p>',5)),i("p",null,[e[1]||(e[1]=i("strong",null,"相關閲讀",-1)),e[2]||(e[2]=a("：",-1)),p(t,{href:"https://www.maketecheasier.com/add-app-drawer-unity-launcher-ubuntu/",title:"How to Add App Drawers to Unity Launcher in Ubuntu"},{default:s(()=>[...e[0]||(e[0]=[a("How to Add App Drawers to Unity Launcher in Ubuntu",-1)])]),_:1})]),e[17]||(e[17]=n(`<h3 id="如何創建桌面啓動器" tabindex="-1">如何創建桌面啓動器 <a class="header-anchor" href="#如何創建桌面啓動器" aria-label="Permalink to “如何創建桌面啓動器”">​</a></h3><p><code>.desktop</code> 文件基本上就是一個包含程序信息的純文本文件，通常根據是自己可見還是所有用户可見的不同而放在 <code>~/.local/share/applications</code> 或者 <code>/usr/share/applications/</code> 目錄中。你在文件管理器中訪問這兩個目錄，都會看到很多系統中已安裝應用對應的 <code>.desktop</code> 文件存在。</p><p>為了演示，我將會為 Super Tux Kart 創建一個 <code>.desktop</code> 文件，這是一個我很喜歡玩的卡丁車競賽遊戲。Ubuntu 倉庫中帶了這個遊戲，但版本一般不新。</p><p>要獲得最新的版本就需要下載 tar 包，解壓並執行其中的遊戲啓動文件。</p><p>你可以仿照這個步驟來為任何程序創建啓動器。</p><p><strong>注意</strong>：下面步驟假設程序壓縮包放在 “Downloads” 目錄下。</p><p>1、跳轉到存放壓縮包的目錄，右擊然後選擇 “Extract here”。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2017/11/application-launcher-5.png" alt="application-launcher-5" title="application-launcher-5"></p><p>2、解壓後，進入新創建的目錄然後找到可執行的文件。之後右擊文件選擇 “Run” 來啓動程序，確定程序運行正常。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2017/11/application-launcher-6.png" alt="application-launcher-6" title="application-launcher-6"></p><p>3、有時候，你在右鍵菜單中找不到 “Run” 選項。這通常是因為這個可執行文件是一個文本文件。你可以在終端中執行它，如果你使用 GNOME 的話，可以點擊上面菜單欄中的 Files 菜單，然後選擇 “Preferences”。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2017/11/application-launcher-linux-1.png" alt="application-launcher-linux-1" title="application-launcher-linux-1"></p><p>4、選擇 “Behavior” 標籤頁然後選擇 “Executable Text Files” 下的 “Run them”。現在右擊可執行文本文件後也能出現 “Run” 選項了。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2017/11/application-launcher-31.png" alt="application-launcher-31" title="application-launcher-31"></p><p>5、確認應用運行正常後，就可以退出它了。然後運行你的文本編輯器並將下面內容粘貼到空文本文件中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Desktop Entry]</span></span>
<span class="line"><span>Encoding=UTF-8</span></span>
<span class="line"><span>Version=1.0</span></span>
<span class="line"><span>Type=Application</span></span>
<span class="line"><span>Terminal=false</span></span>
<span class="line"><span>Exec=/path/to/executable</span></span>
<span class="line"><span>Name=Name of Application</span></span>
<span class="line"><span>Icon=/path/to/icon</span></span></code></pre></div><p>你需要更改 “Exec” 域的值為可執行文件的路徑，並且將 “Name” 域的值改成應用的名稱。大多數的程序都在壓縮包中提供了一個圖標，不要忘記把它也填上哦。在我們這個例子中，Super Tux Kart 的啓動文件看起來是這樣的：</p><p><img src="https://www.maketecheasier.com/assets/uploads/2017/11/application-launcher-supertuxkart.png" alt="application-launcher-supertuxkart" title="application-launcher-supertuxkart"></p><p>6、將文件以 <code>application-name.desktop</code> 為名保存到 <code>~/.local/share/applications</code> 目錄中。<code>.local</code> 目錄位於你的家目錄下，是一個隱藏目錄，你需要啓用 “Show Hidden Files” 模式才能看到它。如果你希望這個應用所有人都能訪問，則在終端中運行下面命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo mv ~/.local/share/applications/&lt;application-name\`.desktop\`&gt; /usr/share/applications/</span></span></code></pre></div><p>當然，別忘了把命令中的 <code>&lt;application-name.desktop&gt;</code> 改成真實的 <code>.desktop</code> 文件名。</p><p>7、完成後，打開應用菜單，就能看到應用出現在其中，可以使用了。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2017/11/application-launcher-2.jpg" alt="application-launcher-2" title="application-launcher-2"></p><p>這個方法應該適用於所有主流的 Linux 操作系統。下面是另一張 Super Tux Kart 在 elementary OS 的應用啓動器 (slingshot) 上的截圖</p><p><img src="https://www.maketecheasier.com/assets/uploads/2017/11/application-launcher-4.jpg" alt="application-launcher-4" title="application-launcher-4"></p><p>如果你覺得本教程還有點用的話，歡迎留言。</p><hr>`,27)),i("p",null,[e[4]||(e[4]=a("via: ",-1)),p(t,{href:"https://www.maketecheasier.com/create-desktop-file-linux/"},{default:s(()=>[...e[3]||(e[3]=[a("https://www.maketecheasier.com/create-desktop-file-linux/",-1)])]),_:1})]),i("p",null,[e[8]||(e[8]=a("作者：",-1)),p(t,{href:"https://www.maketecheasier.com/author/ayoisaiah/"},{default:s(()=>[...e[5]||(e[5]=[a("Ayo Isaiah",-1)])]),_:1}),e[9]||(e[9]=a(" 譯者：",-1)),p(t,{href:"https://github.com/lujun9972"},{default:s(()=>[...e[6]||(e[6]=[a("lujun9972",-1)])]),_:1}),e[10]||(e[10]=a(" 校對：",-1)),p(t,{href:"https://github.com/wxy"},{default:s(()=>[...e[7]||(e[7]=[a("wxy",-1)])]),_:1})]),i("p",null,[e[13]||(e[13]=a("本文由 ",-1)),p(t,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[11]||(e[11]=[a("LCTT",-1)])]),_:1}),e[14]||(e[14]=a(" 原創編譯，",-1)),p(t,{href:"https://linux.cn/"},{default:s(()=>[...e[12]||(e[12]=[a("Linux中國",-1)])]),_:1}),e[15]||(e[15]=a(" 榮譽推出",-1))])])}const b=o(c,[["render",d]]);export{T as __pageData,b as default};
